async function load() {
  const q = new URLSearchParams({ page, limit: 10 });
  if ($("f-tag").value.trim()) q.set("tag", $("f-tag").value.trim());
  if ($("f-done").value) q.set("done", $("f-done").value);
  const res = await fetch("/api/tasks?" + q);
  if (!res.ok) { list.replaceChildren(); $("info").textContent = "Filtro inválido"; return; }
  const { items, total, limit } = await res.json();
  const pages = Math.max(1, Math.ceil(total / limit));
  if (page > pages) { page = pages; return load(); }
  $("info").textContent = `Página ${page} de ${pages} (${total} tarefas)`;
  $("prev").disabled = page <= 1;
  $("next").disabled = page >= pages;
  list.replaceChildren();
  for (const t of items) {
    const li = document.createElement("li");
    if (t.done) li.className = "done";
    const box = document.createElement("input");
    box.type = "checkbox"; box.checked = t.done;
